EXEOF

cd /tmp/blast_primer

echo "=== 按primer看5'截断分布 ==="
echo "说明: sstart=1 表示5'端完整, sstart=2/3/4表示缺了对应碱基数"
echo ""
awk '$3>=90 {key=$2"\t"sstart; c[key]++} END{for(k in c) print k"\t"c[k]}' blast_results.txt | sort -t$'\t' -k1,1 -k2,2n

echo ""
echo "=== 汇总: 每个primer最常缺多少 ==="
awk '$3>=90 {
  sstart[$2][sstart]++
} END {
  for(p in sstart) {
    maxc=0; maxs=0
    for(s in sstart[p]) {
      if(sstart[p][s] > maxc) {maxc=sstart[p][s]; maxs=s}
    }
    printf "%s\t最常见起始位=%d\t该模式出现%d次\n", p, maxs, maxc
  }
}' blast_results.txt | sort -t$'\t' -k2,2n
